const { Parser } = require('json2csv');
const fs = require('fs');

function extractDonationData(donations) {
  return donations.map(donation => {
    const {
      amount,
      state,
      donorBirthday,
      donorEmail,
      donorFirstName,
      donorIdNumber,
      donorLastName,
      donorName,
      donorPublicName,
      receiptType,
      receiptTitle,
      receiptState,
      receiptAddress,
      extraData,
      created_at,
      source_subscription_id,
      donor_id,
    } = donation;

    return {
      amount,
      state,
      donorBirthday,
      donorEmail,
      donorFirstName,
      donorIdNumber,
      donorLastName,
      donorName,
      donorPublicName,
      receiptType,
      receiptTitle,
      receiptState,
      receiptAddress,
      extraEmail: extraData.email,
      extraMobile: extraData.mobile,
      extraLastName: extraData.lastName,
      extraFirstName: extraData.firstName,
      created_at,
      source_subscription_id,
      donor_id,
    };
  });
}

